package com.xianshuyuan.scm.customer.service;
import com.xianshuyuan.scm.common.exception.BusinessException; import com.xianshuyuan.scm.customer.dto.CustomerSkuVisibilityRequest; import com.xianshuyuan.scm.customer.entity.CustomerSkuVisibilityEntity; import java.util.*;
public record CustomerSkuVisibilityChangeSet(List<CustomerSkuVisibilityRequest> inserted,List<CustomerSkuVisibilityRequest> updated,List<Long> removedIds){ public CustomerSkuVisibilityChangeSet{inserted=List.copyOf(inserted);updated=List.copyOf(updated);removedIds=List.copyOf(removedIds);} public static CustomerSkuVisibilityChangeSet between(List<CustomerSkuVisibilityEntity> existing,List<CustomerSkuVisibilityRequest> requested){Map<Long,CustomerSkuVisibilityEntity> unmatched=new LinkedHashMap<>();existing.forEach(v->unmatched.put(v.getId(),v));var ins=new ArrayList<CustomerSkuVisibilityRequest>();var upd=new ArrayList<CustomerSkuVisibilityRequest>();var skuIds=new HashSet<Long>();for(var r:requested){if(!skuIds.add(r.skuId()))throw new BusinessException(CustomerErrorCodes.SKU_NOT_VISIBLE,"SKU 可见性重复");if(r.id()==null){ins.add(r);continue;}if(unmatched.remove(r.id())==null)throw new BusinessException(CustomerErrorCodes.VISIBILITY_NOT_OWNED);upd.add(r);}return new CustomerSkuVisibilityChangeSet(ins,upd,new ArrayList<>(unmatched.keySet()));}}
